import Image from "next/image";
import Link from "next/link";

import { site } from "@/lib/site";
import { cn } from "@/lib/utils";

/**
 * Logo — the Daydreams News lockup (swan + wordmark), drawn from the brand
 * files in `public/brand/` (generated by `scripts/brand-assets.mjs`). Paths
 * and sizes come from `lib/site.ts`, so a new logo is a re-run, not an edit.
 *
 * Heights follow the old masthead metrics so the header does not shift.
 */
const HEIGHTS = { desktop: 56, mobile: 34, compact: 28 } as const;

export function Logo({
  size = "desktop",
  variant = "brand",
  showTagline = true,
  asLink = true,
  className,
}: {
  size?: "desktop" | "mobile" | "compact";
  /** `white` is the footer / dark-band version (reverse colours). */
  variant?: "brand" | "white";
  showTagline?: boolean;
  asLink?: boolean;
  className?: string;
}) {
  const file = variant === "white" ? site.brand.logoReverse : site.brand.logo;
  const height = HEIGHTS[size];
  const width = Math.round((height * file.width) / file.height);

  const content = (
    <span className={cn("flex flex-col", className)}>
      <Image
        src={file.src}
        width={width}
        height={height}
        sizes={`${width}px`}
        alt=""
        loading="eager"
        className="block h-auto max-w-full"
        style={{ width, height: "auto" }}
      />
      {showTagline && size === "desktop" ? (
        <span className="mt-1 pl-[3px] text-[13px] font-medium tracking-[0.2px] text-meta">
          {site.tagline}
        </span>
      ) : null}
      <span className="sr-only">{site.name}</span>
    </span>
  );

  if (!asLink) return content;
  return (
    <Link href="/" aria-label={`${site.name} — ${site.tagline}`}>
      {content}
    </Link>
  );
}

/**
 * Swan mark on a small white tile — compact header, web-story chrome, staff
 * panel. The tile keeps the navy swan legible on dark and photo backgrounds.
 */
export function LogoMark({
  className,
  asLink = true,
  href = "/",
}: {
  /** Sets the tile size, e.g. `size-8`. Defaults to 34 px. */
  className?: string;
  asLink?: boolean;
  href?: string;
}) {
  const mark = (
    <span
      className={cn(
        "grid size-[34px] shrink-0 place-items-center rounded-[6px] bg-white p-[3px] ring-1 ring-black/5",
        className,
      )}
    >
      <Image
        src={site.brand.mark.src}
        width={site.brand.mark.width}
        height={site.brand.mark.height}
        sizes="48px"
        alt=""
        className="block h-auto w-full"
      />
      <span className="sr-only">{site.name}</span>
    </span>
  );
  if (!asLink) return mark;
  return <Link href={href}>{mark}</Link>;
}
